INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('58733868-7f7f-42e3-9d30-2fb9feb7fd05'::uuid, 'card_description', NULL, 'Hierocles lists Biannus among the 22 cities of Crete, and its Hellenistic coins survive. On a hill northwest of modern Viannos, remains run from the Orientalizing period to Roman times.', 'teaser-card-s040-rollback:58733868-7f7f-42e3-9d30-2fb9feb7fd05:card_description', 'rollback of teaser-card-s040: card_description ''Hierocles lists Biannus among the 22 cities of Crete, and its Hellenistic coins survive. On a hill northwest of modern Viannos, remains run from the Orientalizing period to Roman times.'' restored on Biannus', '||126424bf3b510a058d6aa37082bac7c6c60d976817be385e7819fc2df96d0d16', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: Biannus''s Hellenistic coins survive (without the qualifier ''some of which''); S6 says only some of the town''s Hellenistic coins survive; the card''s ''its Hellenistic coins survive'' drops the qualifier ''some'' - write ''some of its Hellenistic coins survive''."}]'::jsonb),
    ('5908e9f0-9f7f-43ee-8fd8-7ac446fd46c7'::uuid, 'card_description', NULL, 'On Sicily''s southeast coast, Helorus was a Greek colony of Syracuse founded in the late 8th century BC. Among them the Colonna Pizzuta, a 10.5-metre column from the 3rd century BC.', 'teaser-card-s040-rollback:5908e9f0-9f7f-43ee-8fd8-7ac446fd46c7:card_description', 'rollback of teaser-card-s040: card_description "On Sicily''s southeast coast, Helorus was a Greek colony of Syracuse founded in the late 8th century BC. Among them the Colonna Pizzuta, a 10.5-metre column from the 3rd century BC." restored on Helorus', '||28cb67afeb577508f92f02f87dcf36df9bd295a3c63c7439a06cc7f75fa45b58', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The tone rules are broken (see the checker''s reasons).; The second sentence ''Among them the Colonna Pizzuta, ...'' is a verbless fragment whose ''them'' refers to nothing in the card; rewrite it as a full sentence, e.g. ''Its major discoveries include the Colonna Pizzuta, a 10.5-metre column from the 3rd century BC.''"}]'::jsonb),
    ('5c40d704-05a0-4951-a5cf-20066d444d81'::uuid, 'card_description', NULL, 'Walton Common, a 25.5 hectare Site of Special Scientific Interest, holds two saucer-shaped Bronze Age round barrows and a late Iron Age banjo enclosure that may be a univallate hillfort.', 'teaser-card-s040-rollback:5c40d704-05a0-4951-a5cf-20066d444d81:card_description', 'rollback of teaser-card-s040: card_description ''Walton Common, a 25.5 hectare Site of Special Scientific Interest, holds two saucer-shaped Bronze Age round barrows and a late Iron Age banjo enclosure that may be a univallate hillfort.'' restored on Walton Common', '||782de1c389657f4463cc8b90ec3a3cf15abf937001ac906d9cf1d8d2dfc7fe60', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): Walton Common holds two round barrows (https://historicengland.org.uk/listing/the-list/list-entry/1007917: \"The saucer barrow represents the earliest known evidence for human activity on the common\") - hedge it or drop it; The web check finds the claim disputed (reputable sources disagree): Both barrows are saucer-shaped (http://web.archive.org/web/20160403080657/http://www.pastscape.org.uk/hob.aspx?hob_id=195444: \"This may be the fragmentary remains of a second circular disc or mutilated saucer barrow which was previously unlocated\") - hedge it or drop it; The web check finds the claim disputed (reputable sources disagree): Walton Common holds a banjo enclosure (https://historicengland.org.uk/listing/the-list/list-entry/1007917: \"Incorrect suggestion of banjo encl\") - hedge it or drop it; The web check finds the claim disputed (reputable sources disagree): The enclosure dates to the late Iron Age (https://historicengland.org.uk/listing/the-list/list-entry/1007917: \"They date between the Late Bronze Age and Early Iron Age (eighth - fifth centuries BC)\") - hedge it or drop it; The web check could not prove: The enclosure may be a univallate hillfort"}]'::jsonb),
    ('5db5e2c0-081a-4c69-a8c6-6105ac870e5f'::uuid, 'card_description', NULL, 'Excavations beneath the floor of the Church of the Holy Apostles Peter and Paul at Ras uncovered black-figure pottery from the 7th-6th centuries BC and a 5th-century BC princely grave.', 'teaser-card-s040-rollback:5db5e2c0-081a-4c69-a8c6-6105ac870e5f:card_description', 'rollback of teaser-card-s040: card_description ''Excavations beneath the floor of the Church of the Holy Apostles Peter and Paul at Ras uncovered black-figure pottery from the 7th-6th centuries BC and a 5th-century BC princely grave.'' restored on Church of the Holy Apostles Peter and Paul, Ras', '||1b165651d68c378098cbbbcb1871046b8a38f284d600c21335a20c824b3c13cd', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-adversarial-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The card states as fact that the 1957 find was a ''princely grave'', but reputable sources disagree on what it was: the Wikipedia article and the Novi Pazar tourist board call it a princely grave or a hoard of the local aristocracy, while Staša Babić''s peer-reviewed critical history (''Princely Graves'' of the Central Balkans, European Journal of Archaeology 5(1), 2002, https://arheo.ffzg.unizg.hr/ska/tekstovi/princely_graves.pdf) describes the objects as having been ''found in a wooden chest by the foundation walls of a medieval church'' and sets the find apart from the excavated graves at Atenica, noting it was only grouped with them as a ''princely grave'' in spite of the perceived differences; the excavators'' own publication (Mano-Zisi and Popović 1969) calls it a ''find'' (nalaz) and Vasić 1996 a ''treasure'' (blago). Hedge the identification (for example ''a rich 5th-century BC deposit, often called a princely grave'') or name the gold-and-silver find without calling it a grave."}]'::jsonb),
    ('5ea99baa-5ab5-4f9f-adb9-48bc53e97363'::uuid, 'card_description', NULL, 'On the southeastern edge of the Abusir necropolis, the Lepsius No.25 Pyramid is a 5th Dynasty double tomb: the eastern tomb measures 27.7 by 21.5 m, and lacked a mortuary temple.', 'teaser-card-s040-rollback:5ea99baa-5ab5-4f9f-adb9-48bc53e97363:card_description', 'rollback of teaser-card-s040: card_description ''On the southeastern edge of the Abusir necropolis, the Lepsius No.25 Pyramid is a 5th Dynasty double tomb: the eastern tomb measures 27.7 by 21.5 m, and lacked a mortuary temple.'' restored on Lepsius No.25 Pyramid', '||5e6063913c774534b6d777bc5b6e973465a6532647162e7fad6714f38f803ecb', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: the eastern tomb lacked a mortuary temple; S3 says the complex lacked a traditional mortuary temple; the card drops ''traditional'' (a sharpened claim) and attaches the lack to the eastern tomb instead of the whole complex - write that the complex lacked a traditional mortuary temple."}]'::jsonb),
    ('5f0df994-58d2-4bd5-91be-252d6ae06f76'::uuid, 'card_description', NULL, 'Outside the walls of Pompeii, the Villa of Diomedes stands on two levels around 3500 square meters, facing what would have been the ancient coast line, though it is not clear it was his.', 'teaser-card-s040-rollback:5f0df994-58d2-4bd5-91be-252d6ae06f76:card_description', 'rollback of teaser-card-s040: card_description ''Outside the walls of Pompeii, the Villa of Diomedes stands on two levels around 3500 square meters, facing what would have been the ancient coast line, though it is not clear it was his.'' restored on Villa of Diomedes', '||ae923f6a2b8e7e6032c5c3296b52d95b848bce7de84da9f68280f8bf2b1cdbc4', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The tone rules are broken (see the checker''s reasons).; ''though it is not clear it was his'' has no antecedent: the card never names Marcus Arrius Diomedes; name him (S4) or drop the clause.; ''stands on two levels around 3500 square meters'' runs two facts together so the area reads as a location; separate them (e.g. ''on two levels, around 3500 square meters in size'').; S7 says the garden side of the building faces the ancient coast line; say ''its garden side faces'' rather than the villa as a whole."}]'::jsonb),
    ('60ef45e0-fd0e-414c-a000-22ddccdd332b'::uuid, 'card_description', NULL, 'Roman occupation at Keal Cotes runs from the 1st to 4th century AD. A 1960s field walk uncovered tessellated mosaic floor tiles; ploughing has left only cropmarks, visible from the air.', 'teaser-card-s040-rollback:60ef45e0-fd0e-414c-a000-22ddccdd332b:card_description', 'rollback of teaser-card-s040: card_description ''Roman occupation at Keal Cotes runs from the 1st to 4th century AD. A 1960s field walk uncovered tessellated mosaic floor tiles; ploughing has left only cropmarks, visible from the air.'' restored on Keal Cotes', '||3b3527859ede025b297e4a08acd26335f7538d8ef4e3d927c0ba2e1963314a20', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: ploughing has left only cropmarks; S3 says agricultural activity has plowed out further excavation possibilities, though cropmark outlines of an extensive dwelling remain visible in aerial photographs; it does not say that only cropmarks are left - drop ''only'' and say that cropmark outlines remain visible from the air."}]'::jsonb),
    ('648faca1-d0ae-4830-83f6-54efdf0231fe'::uuid, 'card_description', NULL, 'Marpa''s ruins straddle both sides of the river in the Cotahuasi Canyon, around 3,400 metres deep. The Inca road may follow an older route built by the Wari culture, circa 500-900 AD.', 'teaser-card-s040-rollback:648faca1-d0ae-4830-83f6-54efdf0231fe:card_description', 'rollback of teaser-card-s040: card_description "Marpa''s ruins straddle both sides of the river in the Cotahuasi Canyon, around 3,400 metres deep. The Inca road may follow an older route built by the Wari culture, circa 500-900 AD." restored on Marpa, Peru', '||e69e22e3583284ebe8209f8ae02c23320aca1e923962b20315af2674d139164e', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): The Wari culture dates to circa 500-900 AD (https://en.wikipedia.org/wiki/Wari_culture: \"from about 500 to 1000 AD\") - hedge it or drop it"}]'::jsonb),
    ('65936955-be6f-43cc-a306-fc879106f442'::uuid, 'card_description', NULL, 'The Tours Amphitheatre stands behind the cathedral in Tours, France, a Roman amphitheatre of the 1st century AD. In front of the Roman amphitheatre, the cathedral stands.', 'teaser-card-s040-rollback:65936955-be6f-43cc-a306-fc879106f442:card_description', 'rollback of teaser-card-s040: card_description ''The Tours Amphitheatre stands behind the cathedral in Tours, France, a Roman amphitheatre of the 1st century AD. In front of the Roman amphitheatre, the cathedral stands.'' restored on Tours Amphitheatre', '||d62fd3e46a1ca2f428b474b6966531b1ed0baf6e41e10ed68b86e79fa03f0241', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The tone rules are broken (see the checker''s reasons).; The second sentence ''In front of the Roman amphitheatre, the cathedral stands.'' only restates the first sentence''s location in reverse; it is filler, not evocative copy - remove it."}]'::jsonb),
    ('6880170a-df11-4dbf-8c6c-02aa4e39ec7b'::uuid, 'card_description', NULL, 'Clunia, an ancient Roman city in present-day Feldkirch, Vorarlberg, Austria, is marked on the Tabula Peutingeriana as a settlement along the Roman road network. The map still names it.', 'teaser-card-s040-rollback:6880170a-df11-4dbf-8c6c-02aa4e39ec7b:card_description', 'rollback of teaser-card-s040: card_description ''Clunia, an ancient Roman city in present-day Feldkirch, Vorarlberg, Austria, is marked on the Tabula Peutingeriana as a settlement along the Roman road network. The map still names it.'' restored on Clunia, Austria', '||68fc657a2c7e5203cc24938c3dd37aeea9fa200606b863873070ab2bc2fb1088', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: the map still names it (the map survives and names it today); No sentence says the Tabula Peutingeriana ''still'' names Clunia or anything about the map surviving today; remove ''The map still names it.''"}]'::jsonb),
    ('68c4944b-9e3a-4561-955c-33fa9978fc86'::uuid, 'card_description', NULL, 'In 1940 a cranium nearly 15,000 years old came to light at the Keilor Archaeological Site. Hearths about 31,000 years BP; megafauna remains suggest a possible Aboriginal hunting link.', 'teaser-card-s040-rollback:68c4944b-9e3a-4561-955c-33fa9978fc86:card_description', 'rollback of teaser-card-s040: card_description ''In 1940 a cranium nearly 15,000 years old came to light at the Keilor Archaeological Site. Hearths about 31,000 years BP; megafauna remains suggest a possible Aboriginal hunting link.'' restored on Keilor Archaeological Site', '||c9bb5d3510a9b86771e652943ea3053d4a22e332cd0bf5bd5e92f93df2e22742', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): The cranium is nearly 15,000 years old (https://www.peterbrown-palaeoanthropology.net/Keilor.html: \"only measure of absolute age was provided by the bone collagen date of 12,000± 100 (NZ-1327)\") - hedge it or drop it"}]'::jsonb),
    ('696fa141-d76e-4882-ab59-75f8a0d46d47'::uuid, 'card_description', NULL, 'Built in the Ionic order, the colonnade of the Garni Temple fell in the earthquake of June 4, 1679 and was rebuilt from its own stones, without mortar, in grey to bluish basalt.', 'teaser-card-s040-rollback:696fa141-d76e-4882-ab59-75f8a0d46d47:card_description', 'rollback of teaser-card-s040: card_description ''Built in the Ionic order, the colonnade of the Garni Temple fell in the earthquake of June 4, 1679 and was rebuilt from its own stones, without mortar, in grey to bluish basalt.'' restored on Garni Temple', '||cabc51ac30d7eb354af6d64e4d5add4ef406c7f591656b343a26562159fd6e4c', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): It was rebuilt from its own (original) stones (https://en.wikipedia.org/wiki/Garni_Temple: \"The surviving pieces comprised about a third of the reconstruction\") - hedge it or drop it"}]'::jsonb),
    ('6a199307-b761-4214-82da-2dbd4c89832c'::uuid, 'card_description', NULL, 'On an isolated 80-metre hilltop, Cannington Camp is a univallate hillfort occupied from the Mesolithic through Roman periods. It is proposed as the site of the 878 AD Battle of Cynuit.', 'teaser-card-s040-rollback:6a199307-b761-4214-82da-2dbd4c89832c:card_description', 'rollback of teaser-card-s040: card_description ''On an isolated 80-metre hilltop, Cannington Camp is a univallate hillfort occupied from the Mesolithic through Roman periods. It is proposed as the site of the 878 AD Battle of Cynuit.'' restored on Cannington Camp', '||1fd4b08caa4107e26315dce4641237afa84fa8bf6cb881fb0eba93199c6590a0', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-adversarial-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: the hillfort was occupied (as a fact, without hedge) from the Mesolithic through the Roman periods; The card sharpens S2''s ''shows evidence of occupation from the Mesolithic through Roman periods'' into a flat statement that the hillfort itself was ''occupied from the Mesolithic through Roman periods'', which reads as continuous occupation of the fort; the reputable sources hedge both ends: the Victoria County History (https://www.british-history.ac.uk/vch/som/vol6/pp73-76) places the Mesolithic material ''at Brymore and in a cave at Cannington Hill'' and calls the fort an Iron Age hillfort that ''seems to have been in use during the Roman period'', and the Historic England list entry 1006225 (https://historicengland.org.uk/listing/the-list/list-entry/1006225) speaks of finds from the Mesolithic to later prehistoric times ''including possible reoccupation during the Romano British period''. Reword to keep the evidential hedge, for example ''finds on the hill range from the Mesolithic to the Roman period''."}]'::jsonb),
    ('6a4cdd7d-42a8-4952-a1b9-7d6bb44f090a'::uuid, 'card_description', NULL, 'The terraces of Quriwayrachina, an archaeological site also called Quri Wayrachina, step across Peru''s Cusco Region in Anta Province, about 4 km north of the terraces of Zurite.', 'teaser-card-s040-rollback:6a4cdd7d-42a8-4952-a1b9-7d6bb44f090a:card_description', 'rollback of teaser-card-s040: card_description "The terraces of Quriwayrachina, an archaeological site also called Quri Wayrachina, step across Peru''s Cusco Region in Anta Province, about 4 km north of the terraces of Zurite." restored on Quriwayrachina, Anta', '||68ec8567d58b43faf91e46442772474a6841d1a44c6bea3659a6b3507413dd8b', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-adversarial-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: the terraces step across (extend across) Peru''s Cusco Region; ''The terraces ... step across Peru''s Cusco Region in Anta Province'' says the terraces extend across the region, which is sharper than S1, which only places the site in the Cusco Region, Anta Province; the Cusco culture directorate''s record (https://web.archive.org/web/20140107111304/http://www.drc-cusco.gob.pe/index.php/zonas-sitios-arqueologicos-anta/importancia-za-anta?showall=&start=7) describes a set of narrow terraces in a young ravine with ''El área es de 6.21has''. Replace ''step across'' with a locating verb such as ''lie in'' or ''climb a ravine in''."}]'::jsonb),
    ('6ee96ec3-9a2f-41be-ad77-f8187a54e493'::uuid, 'card_description', NULL, 'On the southeast coast of Rhodes stands Lartos, an ancient village notable for a major marble formation: lithos lartios, a distinctive gray-blue stone quarried in antiquity.', 'teaser-card-s040-rollback:6ee96ec3-9a2f-41be-ad77-f8187a54e493:card_description', 'rollback of teaser-card-s040: card_description ''On the southeast coast of Rhodes stands Lartos, an ancient village notable for a major marble formation: lithos lartios, a distinctive gray-blue stone quarried in antiquity.'' restored on Lartos, Rhodes', '||22017b7cf58ed506474285250853a7697d65716ee501adaef506973e6543d10f', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: Lartos stands today as an ancient village (present tense); S1 says Lartos ''was an ancient village''; the card''s ''stands Lartos, an ancient village'' turns the past into the present and implies the ancient village still stands - keep the past tense (e.g. ''Lartos was an ancient village'')."}]'::jsonb),
    ('7008f483-697f-4f0b-b2c4-5b234d28d4c7'::uuid, 'card_description', NULL, 'Lakhmir Mound rises in the Naig Valley of Sindh as a conical hill above a lower section resembling a town, where black-on-red pottery of the Indus Valley civilization lies scattered.', 'teaser-card-s040-rollback:7008f483-697f-4f0b-b2c4-5b234d28d4c7:card_description', 'rollback of teaser-card-s040: card_description ''Lakhmir Mound rises in the Naig Valley of Sindh as a conical hill above a lower section resembling a town, where black-on-red pottery of the Indus Valley civilization lies scattered.'' restored on Lakhmir Mound', '||774918b8ed99509c71f505153cf1f05268165530839519ca620f3b13a74281dc', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: black-on-red pottery lies scattered in the lower, town-like section; No sentence of the description supports the claim: the black-on-red pottery is of (belongs to) the Indus Valley civilization; S3 says Chalcolithic pottery fragments are scattered across the mound and surrounding area; the card''s ''where'' places scattered black-on-red pottery in the lower town-like section, which no sentence says.; S3 calls the black-on-red pottery ''characteristic of the Indus Valley civilization''; the card''s ''black-on-red pottery of the Indus Valley civilization'' sharpens this into pottery of that civilization - keep ''characteristic of''.; S3 is an observation attributed to archaeologist N.G. Majumdar (''noted''); the card drops the attribution and states it as a present fact (''lies scattered'')."}]'::jsonb),
    ('72b1b9e1-8e84-402b-b1bd-a7161527bca5'::uuid, 'card_description', NULL, 'Atop Mount Pirwayuq, the site of Pirwayuq sits at approximately 3,900 meters above sea level, in the Laria District of Tayacaja Province in the Huancavelica Region.', 'teaser-card-s040-rollback:72b1b9e1-8e84-402b-b1bd-a7161527bca5:card_description', 'rollback of teaser-card-s040: card_description ''Atop Mount Pirwayuq, the site of Pirwayuq sits at approximately 3,900 meters above sea level, in the Laria District of Tayacaja Province in the Huancavelica Region.'' restored on Pirwayuq', '||00e0cc6c7bbb76f32a433bd0f6985bd726d40672b85aab3e353735956f9c2ad6', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-contradicted", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check contradicts: The site is in Tayacaja Province (http://web.archive.org/web/20160304003348/http://www.mincetur.gob.pe/TURISMO/OTROS/inventario%20turistico/Ficha.asp?cod_Ficha=5170: \"se encuentran ubicados a 3 km del distrito de Laria, provincia y departamento de Huancavelica\")"}]'::jsonb),
    ('75dac040-12f2-4c78-b989-33cd3f5f07a9'::uuid, 'card_description', NULL, 'At Saqqara, stone robbers have left the Pyramid of Neferhetepes a mound of rubble with its burial chamber exposed: it once stood 16.8 m high, built for the wife of Userkaf.', 'teaser-card-s040-rollback:75dac040-12f2-4c78-b989-33cd3f5f07a9:card_description', 'rollback of teaser-card-s040: card_description ''At Saqqara, stone robbers have left the Pyramid of Neferhetepes a mound of rubble with its burial chamber exposed: it once stood 16.8 m high, built for the wife of Userkaf.'' restored on Pyramid of Neferhetepes', '||4b129565af96f6891d3cf2052981bc5add56a939e118b9a93e491d3746c2fc16', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: stone robbers reduced the pyramid to a mound of rubble; S4 credits the stone robbers only with exposing the burial chamber; the card''s ''stone robbers have left the Pyramid of Neferhetepes a mound of rubble'' also makes them the cause of its ruin, which no sentence says - attach the robbers to the exposed chamber only."}]'::jsonb),
    ('75f2454d-5538-42ea-87b2-ba091dec3df6'::uuid, 'card_description', NULL, 'Searching for a Roman road in 1984, the Trent and Peak Archaeological Trust uncovered two Early Neolithic longhouses at Lismore Fields, among the best-preserved in Britain.', 'teaser-card-s040-rollback:75f2454d-5538-42ea-87b2-ba091dec3df6:card_description', 'rollback of teaser-card-s040: card_description ''Searching for a Roman road in 1984, the Trent and Peak Archaeological Trust uncovered two Early Neolithic longhouses at Lismore Fields, among the best-preserved in Britain.'' restored on Lismore Fields', '||1ce66801970c215313edf0f9dc20551c97da01c836d6ee455faa76212a8a4296', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: the Trust uncovered the two longhouses in 1984 during that search; S1 says only that the site was discovered in 1984 by the Trent and Peak Archaeological Trust while searching for a Roman road; S2 says the longhouses were revealed by excavations, without date or excavator - the card''s claim that the Trust uncovered the longhouses in 1984 while searching for the road joins the two into a statement no sentence makes."}]'::jsonb),
    ('76bd4687-787b-48d8-bbb5-e0d063bbf4c6'::uuid, 'card_description', NULL, 'At Colebrooke, Devon, the agger of a Roman road still shows in a field roughly 300 metres south of Rag Lane. It fades near the village, yet a straight lane along the ridge suggests its line.', 'teaser-card-s040-rollback:76bd4687-787b-48d8-bbb5-e0d063bbf4c6:card_description', 'rollback of teaser-card-s040: card_description ''At Colebrooke, Devon, the agger of a Roman road still shows in a field roughly 300 metres south of Rag Lane. It fades near the village, yet a straight lane along the ridge suggests its line.'' restored on Colebrooke, Devon', '||0e135ed552d38b846dfff1346d04ae7973a9420d348d1a91d5537aff157d0351', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-unproven", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check could not prove: The field with the visible agger lies roughly 300 metres south of Rag Lane; The web check could not prove: That straight lane runs along the ridge"}]'::jsonb),
    ('79132373-7a68-45e3-a174-3b1e429a12b3'::uuid, 'card_description', NULL, 'The northernmost point of Spain, Punta da Estaca de Bares reaches into the Cantabrian Sea and takes more than 2500 mm of rain a year, one of the rainiest places in Europe.', 'teaser-card-s040-rollback:79132373-7a68-45e3-a174-3b1e429a12b3:card_description', 'rollback of teaser-card-s040: card_description ''The northernmost point of Spain, Punta da Estaca de Bares reaches into the Cantabrian Sea and takes more than 2500 mm of rain a year, one of the rainiest places in Europe.'' restored on Punta de Estaca de Bares', '||efb27e6a18427e66579e8fb88480365a850f1cf532b9178b5a86d045335b57bd', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): It takes more than 2500 mm of rain a year (https://es.wikipedia.org/wiki/Estaca_de_Bares: \"Precipitaciones: 1370 mm\") - hedge it or drop it; The web check finds the claim disputed (reputable sources disagree): It is one of the rainiest places in Europe (https://es.wikipedia.org/wiki/Estaca_de_Bares: \"Precipitaciones: 1370 mm\") - hedge it or drop it"}]'::jsonb),
    ('7cfc73a7-180b-4378-a14a-785e9cab28a4'::uuid, 'card_description', NULL, 'About 3 km south of Manfredonia, Siponto was a port town and bishopric of Magna Graecia. In 189 BC it became the Roman colony Sipontum; in 663 AD the Slavs took and destroyed it.', 'teaser-card-s040-rollback:7cfc73a7-180b-4378-a14a-785e9cab28a4:card_description', 'rollback of teaser-card-s040: card_description ''About 3 km south of Manfredonia, Siponto was a port town and bishopric of Magna Graecia. In 189 BC it became the Roman colony Sipontum; in 663 AD the Slavs took and destroyed it.'' restored on Siponto', '||9c30943decd70affc214cb4eae0f359003b8300933a8e98167fc3c0aed69caf7', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): Siponto was a town of Magna Graecia (https://www.treccani.it/enciclopedia/siponto_(Enciclopedia-Italiana)/: \"Città antica nella Daunia, fondata, secondo una leggenda comune a moltissime città dell''Adriatico, da Diomede\") - hedge it or drop it; The web check finds the claim disputed (reputable sources disagree): It became a Roman colony in 189 BC (https://www.treccani.it/enciclopedia/siponto_(Enciclopedia-Italiana)/: \"questi nel 194 a. C. dedussero a Siponto una colonia\") - hedge it or drop it; The web check finds the claim disputed (reputable sources disagree): The Slavs took it in 663 AD (https://www.treccani.it/enciclopedia/siponto_(Enciclopedia-Italiana)/: \"Fu poi depredata da Slavoni (642), da Longobardi, da Saraceni\") - hedge it or drop it; The web check finds the claim disputed (reputable sources disagree): The Slavs destroyed Siponto (https://www.treccani.it/enciclopedia/siponto_(Enciclopedia-Italiana)/: \"Fu poi depredata da Slavoni (642), da Longobardi, da Saraceni\") - hedge it or drop it"}]'::jsonb),
    ('7e88e3ce-568c-4cea-aa71-79713b290df1'::uuid, 'card_description', NULL, 'Near the village of Berel in eastern Kazakhstan, Berel Kurgan holds numerous 5th-3rd century BCE Early Saka kurgans, vast quantities of golden jewelry, and horses buried beside their owners.', 'teaser-card-s040-rollback:7e88e3ce-568c-4cea-aa71-79713b290df1:card_description', 'rollback of teaser-card-s040: card_description ''Near the village of Berel in eastern Kazakhstan, Berel Kurgan holds numerous 5th-3rd century BCE Early Saka kurgans, vast quantities of golden jewelry, and horses buried beside their owners.'' restored on Berel Kurgan', '||d4cc57e388ea1c10ec59367ef8dda731aa6d1cd72cc8322f0d515f576a1bafc8', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: the site holds vast quantities of golden jewelry today; S4 says the kurgans contained (past tense) vast quantities of golden jewelry; the card''s present-tense ''holds ... vast quantities of golden jewelry'' says the jewelry is still at the site, which no sentence says - write that the kurgans contained it."}]'::jsonb),
    ('81724be4-6588-41b1-8efc-364637456cdf'::uuid, 'card_description', NULL, 'Cut into the upper slopes of Whitehorse Hill in Oxfordshire, the Uffington White Horse runs 110 m in trenches of crushed white chalk, made between 1380 and 550 BC.', 'teaser-card-s040-rollback:81724be4-6588-41b1-8efc-364637456cdf:card_description', 'rollback of teaser-card-s040: card_description ''Cut into the upper slopes of Whitehorse Hill in Oxfordshire, the Uffington White Horse runs 110 m in trenches of crushed white chalk, made between 1380 and 550 BC.'' restored on Uffington White Horse', '||a599d7655c16257dbf7822482579633734fa1d3f5273526e30f911d7f6b07515', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): It runs 110 m (https://www.oxfordarchaeology.com/uffington-white-horse: \"It is 120 metres long\") - hedge it or drop it"}]'::jsonb),
    ('8797faec-8590-4716-9763-310be93ef6ea'::uuid, 'card_description', NULL, 'Outside the city walls of Palmyra, in the Valley of the Tombs, stood the Tower of Elahbel. In its tombs were found fragments of very early Chinese silk yarns dated to the 1st century AD.', 'teaser-card-s040-rollback:8797faec-8590-4716-9763-310be93ef6ea:card_description', 'rollback of teaser-card-s040: card_description ''Outside the city walls of Palmyra, in the Valley of the Tombs, stood the Tower of Elahbel. In its tombs were found fragments of very early Chinese silk yarns dated to the 1st century AD.'' restored on Tower of Elahbel', '||b2f22feb90539ef295224d2e23d88bf09d4e758085e241696c4d7da5fbeb55b8', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): The silk yarns are dated to the 1st century AD (https://bibleinterp.arizona.edu/articles/2013/mie378011: \"The silk textile fragments recovered from the tombs at Palmyra date between 9 BCE (Towertomb 7, Atenatan) and 103 CE (Towertomb 13, Elahbel)\") - hedge it or drop it"}]'::jsonb),
    ('8ef67a96-2590-4382-b575-4a15f7c468fe'::uuid, 'card_description', NULL, 'Cova Foradà, a cave in a low hill near Oliva, gave up a maxilla and fragments of a cranium. In 2010 came the most complete Neanderthal skeleton ever found on the Iberian peninsula.', 'teaser-card-s040-rollback:8ef67a96-2590-4382-b575-4a15f7c468fe:card_description', 'rollback of teaser-card-s040: card_description ''Cova Foradà, a cave in a low hill near Oliva, gave up a maxilla and fragments of a cranium. In 2010 came the most complete Neanderthal skeleton ever found on the Iberian peninsula.'' restored on Cova Foradà', '||e1a12dd3cd758995eae5450098b5ae2816cdf2c106c8b4a83a099fa42f329f40', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): The 2010 skeleton is the most complete Neanderthal skeleton ever found on the Iberian peninsula (https://popular-archaeology.com/article/the-neanderthals-of-sima-de-las-palomas/: \"The skeleton is about 85% complete\") - hedge it or drop it"}]'::jsonb),
    ('9116c105-f7ac-4f02-8ea4-b724c68c9464'::uuid, 'card_description', NULL, 'At Heraclea Lyncestis, the Roman emperor Hadrian built a theatre on a hill. In the Great Basilica, three naves are covered with mosaics of very rich floral and figurative iconography.', 'teaser-card-s040-rollback:9116c105-f7ac-4f02-8ea4-b724c68c9464:card_description', 'rollback of teaser-card-s040: card_description ''At Heraclea Lyncestis, the Roman emperor Hadrian built a theatre on a hill. In the Great Basilica, three naves are covered with mosaics of very rich floral and figurative iconography.'' restored on Heraclea Lyncestis', '||a16031bf357c12fdf853e1e1534a22dec46d4b4fa6f68b1bf608d8579cf50197', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check could not prove: The Great Basilica has three naves; The web check finds the claim disputed (reputable sources disagree): The nave mosaics show very rich floral and figurative iconography (https://muzejbitola.mk/en/mosaic-nartex/: \"The oldest Early-Christianity mosaics are represented by geometric motifs (loops, diamond cross, crossed circles), such as mosaics of the central aisle and deaconry of the Great Basilica\") - hedge it or drop it"}]'::jsonb),
    ('94e18246-8ec7-4da8-9bad-ea33e78d2dcb'::uuid, 'card_description', NULL, 'Stobi stands near Gradsko, where the Erigon joins the Axios, on the road from the Danube to the Aegean. Its theatre was built in the 3rd century, and it kept a large number of mosaics.', 'teaser-card-s040-rollback:94e18246-8ec7-4da8-9bad-ea33e78d2dcb:card_description', 'rollback of teaser-card-s040: card_description ''Stobi stands near Gradsko, where the Erigon joins the Axios, on the road from the Danube to the Aegean. Its theatre was built in the 3rd century, and it kept a large number of mosaics.'' restored on Stobi', '||376efd97646d83b2362e6c7c9eff68002bd4057d543cb4e67f6198ea3e711c20', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-contradicted", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check contradicts: Its theatre was built in the 3rd century (https://stobi.mk/en/stobi-2/the-city/the-theatre/: \"Construction began towards the end of the 1st century AD\")"}]'::jsonb),
    ('96395824-9c31-477a-bf51-13ecb5035d56'::uuid, 'card_description', NULL, 'Pintia was besieged and destroyed by the Romans, and with it went the Vaccean culture, religion and language. The zone has three parts: a city, a necropolis and a potter''s district.', 'teaser-card-s040-rollback:96395824-9c31-477a-bf51-13ecb5035d56:card_description', 'rollback of teaser-card-s040: card_description "Pintia was besieged and destroyed by the Romans, and with it went the Vaccean culture, religion and language. The zone has three parts: a city, a necropolis and a potter''s district." restored on Pintia', '||bd17b9cd25bc0d72f56eabe8d02a8c8e5671bc0a1a36f8f5638bfa183e53fc69', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-contradicted", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check contradicts: Pintia was destroyed by the Romans (https://www.pintiavaccea.es/seccion/las-quintanas: \"Tras el proceso de conquista romana, la ciudad de Pintia continuó su existencia\"); The web check could not prove: Pintia was besieged by the Romans; The web check contradicts: With Pintia''s destruction the Vaccean culture, religion and language came to an end (https://www.pintiavaccea.es/seccion/la-herencia-de-los-vacceos: \"como la disolución del sistema cultural vacceo fraguado a lo largo del primer milenio a. C.\")"}]'::jsonb),
    ('97fb3d8b-5f53-4233-a31e-80c6b2b5228a'::uuid, 'card_description', NULL, 'Daskalio, a tiny islet off Keros in the Cyclades, was once a promontory before the sea rose. Metalworking workshops dating from 2500 BCE were found there, and Naxos marble terraces it.', 'teaser-card-s040-rollback:97fb3d8b-5f53-4233-a31e-80c6b2b5228a:card_description', 'rollback of teaser-card-s040: card_description ''Daskalio, a tiny islet off Keros in the Cyclades, was once a promontory before the sea rose. Metalworking workshops dating from 2500 BCE were found there, and Naxos marble terraces it.'' restored on Daskalio', '||50b837ef9f187082b9349f8f7448891fee2bee36f5f0a0fdf9ee277199a1d847', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: metalworking workshops dating from 2500 BCE were found there; S3 says researchers found evidence of advanced metalworking workshops dating from 2500 BCE; the card says the workshops themselves were found, which drops the hedge ''evidence of'' - keep it (''evidence of metalworking workshops'')."}]'::jsonb),
    ('996e0b32-f8ca-4d04-8900-ed937b729269'::uuid, 'card_description', NULL, 'Five caves on the western shore of the Mani Peninsula make up Apidima Cave. Apidima 2, with Neanderthal morphology, was dated to more than 170,000 years; Apidima 1 is older.', 'teaser-card-s040-rollback:996e0b32-f8ca-4d04-8900-ed937b729269:card_description', 'rollback of teaser-card-s040: card_description ''Five caves on the western shore of the Mani Peninsula make up Apidima Cave. Apidima 2, with Neanderthal morphology, was dated to more than 170,000 years; Apidima 1 is older.'' restored on Apidima Cave', '||e3837d14ce6b6e6fc328f959f5e804b9d8322e2eb050221081eb231305c71d0a', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: Apidima 2 has Neanderthal morphology; S5 says only that research published in July 2019 indicates that the Apidima 2 skull fragment has Neanderthal morphology; the card states the Neanderthal morphology as plain fact, dropping the attribution and the hedge ''indicates'' - keep them (e.g. ''research indicates Neanderthal morphology'')."}]'::jsonb),
    ('a692e959-c6b4-45b5-96f6-65b82c883a35'::uuid, 'card_description', NULL, 'Taliata was a Roman fort on the Moesian Limes, the chain of forts along the Danube. Domitian gave its wood and earth walls stone faces in 87 AD; an early Christian basilica was found there.', 'teaser-card-s040-rollback:a692e959-c6b4-45b5-96f6-65b82c883a35:card_description', 'rollback of teaser-card-s040: card_description ''Taliata was a Roman fort on the Moesian Limes, the chain of forts along the Danube. Domitian gave its wood and earth walls stone faces in 87 AD; an early Christian basilica was found there.'' restored on Taliata', '||d6f1d857d95fd2264ccbd1722a5cdbf7a31c28b25cac94f3485743c2d16a9792', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: in 87 AD Domitian gave its wood and earth walls stone faces (stone cladding over the old walls); S4 says Domitian replaced the wood and earth walls by stone walls in 87 AD; the card says he gave the wood and earth walls stone faces, i.e. clad the old walls in stone, which no sentence says - write that he replaced them with stone walls."}]'::jsonb),
    ('a945d5ef-bbbf-42bd-be5b-27c25eda9df1'::uuid, 'card_description', NULL, 'At Aguadulce in Almería, the site of La Ribera de Algaida covers 20 to 30 hectares and was occupied from the Argaric culture until the Roman Era. It was discovered in 1859.', 'teaser-card-s040-rollback:a945d5ef-bbbf-42bd-be5b-27c25eda9df1:card_description', 'rollback of teaser-card-s040: card_description ''At Aguadulce in Almería, the site of La Ribera de Algaida covers 20 to 30 hectares and was occupied from the Argaric culture until the Roman Era. It was discovered in 1859.'' restored on Archaeological Site of La Ribera de Algaida', '||2689c7a8d7cfbff7a3e06ba3db02ea1898abe8c3355099fb53c66f64a77280e9', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-contradicted", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check contradicts: The site covers 20 to 30 hectares (https://novaciencia.es/turaniana-un-yacimiento-romano-en-los-bajos-de-roquetas-de-mar/: \"La extensión del yacimiento aproximadamente es de unas 13 hectáreas\"); The web check contradicts: The site''s occupation lasted until the Roman Era (https://es.wikipedia.org/wiki/Yacimiento_arqueol%C3%B3gico_de_La_Ribera_de_la_Algaida: \"Ocupación histórica ininterrumpida de 5.000 años, desde la Edad del Cobre hasta el siglo XII\")"}]'::jsonb),
    ('b7cc5073-ffca-4cd3-a168-3062908d4959'::uuid, 'card_description', NULL, 'On top of a South Downs hill, the Beacon Hill fort is a single rampart and a flat-bottomed ditch, now a low bank up to 6 metres wide. The area also holds an Anglo-Saxon burial mound.', 'teaser-card-s040-rollback:b7cc5073-ffca-4cd3-a168-3062908d4959:card_description', 'rollback of teaser-card-s040: card_description ''On top of a South Downs hill, the Beacon Hill fort is a single rampart and a flat-bottomed ditch, now a low bank up to 6 metres wide. The area also holds an Anglo-Saxon burial mound.'' restored on Beacon Hill, West Sussex', '||ca9aa13116848c72b888924d605b5c9d230a2484f59f6598b9ca57f2797bbaa8', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-contradicted", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check could not prove: The rampart is accompanied by a flat-bottomed ditch; The web check could not prove: The rampart now survives as a low bank up to 6 metres wide; The web check contradicts: The area (present tense) holds an Anglo-Saxon burial mound (https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA193150: \"Under grass and not visible on ground\")"}]'::jsonb),
    ('b8f4c5f4-c567-4605-9f3d-9475d2db6362'::uuid, 'card_description', NULL, 'In Dulan Village, the Dulan Site holds a rectangular stony coffin, dug during Japanese rule, and a giant stone pile found by Academia Sinica. Its objects date back to 3,000 years ago.', 'teaser-card-s040-rollback:b8f4c5f4-c567-4605-9f3d-9475d2db6362:card_description', 'rollback of teaser-card-s040: card_description ''In Dulan Village, the Dulan Site holds a rectangular stony coffin, dug during Japanese rule, and a giant stone pile found by Academia Sinica. Its objects date back to 3,000 years ago.'' restored on Dulan Site', '||fddeeb9ee4134ed1517660440e5c97f4c77b6334de12b0a183cad4b84cc6f9a4', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: the site currently holds a rectangular stony coffin; S2 says only that a rectangular stony coffin was excavated in the area during Japanese rule; the present-tense ''holds'' claims the coffin is still at the site, which no sentence says - write that the site yielded the coffin instead."}]'::jsonb),
    ('c17927cb-4b63-4fa0-9c64-b72a65decaaa'::uuid, 'card_description', NULL, 'On Rhodes in the Dodecanese, the acropolis of Lindos was dominated by the massive temple of Athena Lindia, which attained its final form around 300 BC, and was excavated down to bedrock.', 'teaser-card-s040-rollback:c17927cb-4b63-4fa0-9c64-b72a65decaaa:card_description', 'rollback of teaser-card-s040: card_description ''On Rhodes in the Dodecanese, the acropolis of Lindos was dominated by the massive temple of Athena Lindia, which attained its final form around 300 BC, and was excavated down to bedrock.'' restored on Lindos', '||7d41e378a59967ef66932f509a3d28258f5ffa26b5f446aaa9cbf3c0afe2a368', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-contradicted", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check contradicts: The temple of Athena Lindia was massive (https://topostext.org/place/361281PLin: \"The Temple of Athena itself seems small after such a grand approach: it measures only 22m x 8m\")"}]'::jsonb),
    ('c8529ed4-208b-45d2-9e75-58a5c3022c82'::uuid, 'card_description', NULL, 'The ruins of Pushkalavati are two sites, Bala Hisar to the south and Shaikhan Dheri to the north. According to Arrian, the city surrendered in 327/326 BCE to Alexander the Great.', 'teaser-card-s040-rollback:c8529ed4-208b-45d2-9e75-58a5c3022c82:card_description', 'rollback of teaser-card-s040: card_description ''The ruins of Pushkalavati are two sites, Bala Hisar to the south and Shaikhan Dheri to the north. According to Arrian, the city surrendered in 327/326 BCE to Alexander the Great.'' restored on Pushkalavati', '||8bf9a7d0b91528211506fa1e838a7078a0829f07f96839565e459930fec39843', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): The ruins of Pushkalavati consist of two sites (https://de.wikipedia.org/wiki/Pushkalavati: \"Die Stadt bestand aus drei Siedlungszentren.\") - hedge it or drop it"}]'::jsonb),
    ('c8e0a91d-298d-40f1-aef8-f8503e44b05a'::uuid, 'card_description', NULL, 'Across the fens, the Fen Causeway runs 24 miles from Denver to Peterborough, thought raised on gravel up to 60 feet wide. Near its western end lies the Bronze Age route across Flag Fen.', 'teaser-card-s040-rollback:c8e0a91d-298d-40f1-aef8-f8503e44b05a:card_description', 'rollback of teaser-card-s040: card_description ''Across the fens, the Fen Causeway runs 24 miles from Denver to Peterborough, thought raised on gravel up to 60 feet wide. Near its western end lies the Bronze Age route across Flag Fen.'' restored on Fen Causeway', '||5f894d3b2c07759df8cf2321f2e110fa56337a61d7e3fafa707796b9d4ede79e', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): The gravel road was up to 60 feet wide (https://www.heritage.norfolk.gov.uk/record-details?MNF2796-Fen-Causeway-Roman-road=: \"It was described as very hard set gravel, three feet thick by 60 feet wide, and much barrelled. However, this has since been interpreted by R. R. Clarke as a roddon\") - hedge it or drop it"}]'::jsonb),
    ('ccb3de8b-5c50-4204-ae6f-46cdda2e081d'::uuid, 'card_description', NULL, 'Red-painted pottery drew the first interest in Ban Chiang in 1966. At least 142 burials were dug in 1974-1975, giving up bracelets, rings, anklets, spearheads and little bells.', 'teaser-card-s040-rollback:ccb3de8b-5c50-4204-ae6f-46cdda2e081d:card_description', 'rollback of teaser-card-s040: card_description ''Red-painted pottery drew the first interest in Ban Chiang in 1966. At least 142 burials were dug in 1974-1975, giving up bracelets, rings, anklets, spearheads and little bells.'' restored on Ban Chiang', '||214f2a5947ee3a3ce57b90240df3f2f0c270edde05d7b6a3d9b09e531c80fc4e', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: those 1974-1975 burials gave up bracelets, rings, anklets, spearheads and little bells; S6 lists the recovered bronze objects without saying they came from the 142 burials of the 1974-1975 excavations; ''giving up'' ties them to those burials, which no sentence does - state the finds separately from the 1974-1975 burials."}]'::jsonb),
    ('cdecef79-7895-4765-af67-14e60868a220'::uuid, 'card_description', NULL, 'Low-relief carvings cut into the rocks 22 kilometres from Tacna show people fighting, dancing and hunting animals. Many believe the Miculla Petroglyphs are around 1500 years old.', 'teaser-card-s040-rollback:cdecef79-7895-4765-af67-14e60868a220:card_description', 'rollback of teaser-card-s040: card_description ''Low-relief carvings cut into the rocks 22 kilometres from Tacna show people fighting, dancing and hunting animals. Many believe the Miculla Petroglyphs are around 1500 years old.'' restored on Miculla Petroglyphs', '||eb89a564e7ccc575c129507455a931badcb3de3161aaf45c8ed88b4aa8c146e5', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): Many believe the petroglyphs are around 1500 years old (https://diariocorreo.pe/edicion/tacna/hallazgo-arqueologico-descubren-1058-petroglifos-y-12-entierros-en-miculla-tacna-noticia/: \"tienen una antigüedad de más de 1,500 años antes de Cristo\") - hedge it or drop it"}]'::jsonb),
    ('cee33cc0-9de5-493c-b43b-82678a6b1d8b'::uuid, 'card_description', NULL, 'On both banks of the Miño river sits Ourense, ancient Auria. The Moors destroyed it in 716; Alfonso III of Asturias rebuilt it about 877, and Al-Mansur''s attacks laid it to waste again.', 'teaser-card-s040-rollback:cee33cc0-9de5-493c-b43b-82678a6b1d8b:card_description', 'rollback of teaser-card-s040: card_description "On both banks of the Miño river sits Ourense, ancient Auria. The Moors destroyed it in 716; Alfonso III of Asturias rebuilt it about 877, and Al-Mansur''s attacks laid it to waste again." restored on Ourense', '||5fb860eaf6396196c06c49491e116c32a888686fdb20f2db49247cab36b7f294', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check finds the claim disputed (reputable sources disagree): The rebuilding took place about 877 (https://en.wikisource.org/wiki/1911_Encyclop%C3%A6dia_Britannica/Orense_(city): \"it was sacked by the Moors in 716, and rebuilt only in 884.\") - hedge it or drop it"}]'::jsonb),
    ('d70dd131-fac7-4c7e-b367-95c2ac945339'::uuid, 'card_description', NULL, 'Queens, princes and high-ranking officials were buried in the Valley of the Queens from roughly 1560 BC to 1130 BC. The ancients called it Ta-Set-Neferu, the Place of Beauty.', 'teaser-card-s040-rollback:d70dd131-fac7-4c7e-b367-95c2ac945339:card_description', 'rollback of teaser-card-s040: card_description ''Queens, princes and high-ranking officials were buried in the Valley of the Queens from roughly 1560 BC to 1130 BC. The ancients called it Ta-Set-Neferu, the Place of Beauty.'' restored on Valley of the Queens', '||0a75ddfe18ef6cf846e40b5f21c294405089a5271fb002aa4c25497565c0c8a1', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-adversarial-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The card glosses Ta-Set-Neferu flatly as ''the Place of Beauty'', but S2 gives a double meaning (''The Place of Beauty'' and/or ''the Place of the Royal Children'') and scholars disagree on the reading: the Project QV66 page https://www.nefertaritomb.com/walley states ''The meaning of the Pharaonic name of the Valley – Ta Set Neferu – is subject to different interpretations. According to Leblanc, Ta Set Neferu has the meaning ‘the Place of the Royal Children’'', while ''Other scholars translate Ta Set Neferu as ‘The Place of Beauty,’ nfrw being given the meaning of ‘beauty’ or ‘perfection,’'' - so the card must hedge the translation (for example ''often read as the Place of Beauty, or the Place of the Royal Children'') or drop it."}]'::jsonb),
    ('e0191dff-1a40-4bd3-bfb4-1ea65cc1c2ca'::uuid, 'card_description', NULL, 'Along the Oude Rijn, the north border of the Roman Empire, stood Alphen aan den Rijn: Roman forts, the first bridge over the river, and a busy trade that ended in 240 AD.', 'teaser-card-s040-rollback:e0191dff-1a40-4bd3-bfb4-1ea65cc1c2ca:card_description', 'rollback of teaser-card-s040: card_description ''Along the Oude Rijn, the north border of the Roman Empire, stood Alphen aan den Rijn: Roman forts, the first bridge over the river, and a busy trade that ended in 240 AD.'' restored on Alphen aan den Rijn', '||1453ca36f4c4e67ea1436414f8b6c1601f12bf13ed9f0e2d97e59c4fcd6cbc98', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: Alphen had Roman forts (plural); S4 says several Roman fortifications stood along the Oude Rijn, only one of them (castellum Albanianae) in the centre of Alphen; the card''s ''Alphen: Roman forts'' gives Alphen several forts - name the one castellum in Alphen or place the forts along the river."}]'::jsonb),
    ('e364d6eb-f92a-44d7-80b2-025092a81561'::uuid, 'card_description', NULL, 'On a hillock across the Ravi from the city, Multan Fort''s walls rose 40 to 70 feet high around 46 bastions. The Mughal prince Murad Bakhsh built them in the 17th century.', 'teaser-card-s040-rollback:e364d6eb-f92a-44d7-80b2-025092a81561:card_description', 'rollback of teaser-card-s040: card_description "On a hillock across the Ravi from the city, Multan Fort''s walls rose 40 to 70 feet high around 46 bastions. The Mughal prince Murad Bakhsh built them in the 17th century." restored on Multan Fort', '||3f02e4902e82f3ed8803bc438458a6b79db6504c14e7ab46f740cc7e1bda5df6', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: the fort''s walls rose 40 to 70 feet high; S6 gives the 40 to 70 feet height only as what contemporary reports put it at; the card states it as fact - keep the attribution (e.g. ''contemporary reports put its walls at 40 to 70 feet'')."}]'::jsonb),
    ('ee0017b2-44f4-426d-8901-5842c832eb30'::uuid, 'card_description', NULL, 'Before Nîmes was the Roman colony of Colonia Nemausus, semi-nomadic cultivators worked its Neolithic site of Serre Paradis from 4000 to 3500 BCE. Augustus ringed the city with ramparts.', 'teaser-card-s040-rollback:ee0017b2-44f4-426d-8901-5842c832eb30:card_description', 'rollback of teaser-card-s040: card_description ''Before Nîmes was the Roman colony of Colonia Nemausus, semi-nomadic cultivators worked its Neolithic site of Serre Paradis from 4000 to 3500 BCE. Augustus ringed the city with ramparts.'' restored on Nîmes', '||389d09d376bf6568d3fdde1bbe11c0979155b377c4e50db6827198a5291cdfc8', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-unproven", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check could not prove: Nîmes has a Neolithic site called Serre Paradis that predates the Roman colony; The web check could not prove: Semi-nomadic cultivators worked the Serre Paradis site; The web check could not prove: The Serre Paradis occupation dates from 4000 to 3500 BCE"}]'::jsonb),
    ('efe2bc83-83cc-4393-b725-a18543dc9d5f'::uuid, 'card_description', NULL, 'Almost all dolmens around the Mediterranean are oriented to a celestial feature. At the Antequera Dolmens Site, the Dolmen of Menga points instead at the nearby Peña de los Enamorados.', 'teaser-card-s040-rollback:efe2bc83-83cc-4393-b725-a18543dc9d5f:card_description', 'rollback of teaser-card-s040: card_description ''Almost all dolmens around the Mediterranean are oriented to a celestial feature. At the Antequera Dolmens Site, the Dolmen of Menga points instead at the nearby Peña de los Enamorados.'' restored on Antequera Dolmens Site', '||c61e6f567b29dd8de8e9948b8549d6294990b679ed24eed79c054a6d7049ebb6', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-check-failed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "No sentence of the description supports the claim: almost all dolmens around the Mediterranean are oriented to a celestial feature; S5 gives the statement that almost all Mediterranean dolmens are oriented to a celestial feature only as what the archaeoastronomer Michael Hoskin noted; the card states it as fact - keep the attribution to Hoskin."}]'::jsonb),
    ('fc337c87-1194-4407-b440-2b91f93dbdc7'::uuid, 'card_description', NULL, 'In 1983 Cecilio Barroso and Paqui Medina found a Neanderthal mandible in a cave at Zafarraya, dated to 30,000 years BP. Mousterian tools lay near it, dated to 27,000 years BP.', 'teaser-card-s040-rollback:fc337c87-1194-4407-b440-2b91f93dbdc7:card_description', 'rollback of teaser-card-s040: card_description ''In 1983 Cecilio Barroso and Paqui Medina found a Neanderthal mandible in a cave at Zafarraya, dated to 30,000 years BP. Mousterian tools lay near it, dated to 27,000 years BP.'' restored on Zafarraya', '||b34124238458339ff6bbf6fb8aedd96c10cac0da2cd64be19def94760fb47dba', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-disputed", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check could not prove: Zafarraya has a cave (Cueva del Boquete de Zafarraya) in Spain that is a Neanderthal fossil site; The web check could not prove: Paqui Medina found the mandible together with Cecilio Barroso; The web check finds the claim disputed (reputable sources disagree): The mandible is dated to 30,000 years BP (https://pmc.ncbi.nlm.nih.gov/articles/PMC3581959/: \"close to or beyond the limit of the radiocarbon method for the Mousterian at Jarama VI and Neanderthal fossils at Zafarraya\") - hedge it or drop it; The web check finds the claim disputed (reputable sources disagree): The Mousterian tools are dated to 27,000 years BP (https://archive.archaeology.org/9509/newsbriefs/neander.html: \"Two other samples were not directly associated with Neandertal remains. One, from an upper level, yielded a carbon date of 29,800 B.P. and a Th/U date of 27,000 B.P.\") - hedge it or drop it"}]'::jsonb),
    ('fee2da6d-ac67-4e7c-92b9-fbb82ae6bf8a'::uuid, 'card_description', NULL, 'The Roman Emperors Route spans 600 km across Serbia, through the Roman cities of Sirmium, Felix Romuliana and Naissus, in a land where 17 Roman emperors were born.', 'teaser-card-s040-rollback:fee2da6d-ac67-4e7c-92b9-fbb82ae6bf8a:card_description', 'rollback of teaser-card-s040: card_description ''The Roman Emperors Route spans 600 km across Serbia, through the Roman cities of Sirmium, Felix Romuliana and Naissus, in a land where 17 Roman emperors were born.'' restored on Roman Emperors Route', '||0c19068e913a41dbe338b12ed8322fb705a5de00b227ec788748ff4e3a6b6e01', '[{"source": "lane WB run wb-recheck-2026-10-24: recheck-contradicted", "url": "output/remediation/teaser/runs/wb-recheck-2026-10-24/OUTCOMES.jsonl", "quote": "The web check contradicts: Felix Romuliana is a Roman city (https://en.wikipedia.org/wiki/Felix_Romuliana: \"Systematic archaeological excavations conducted since 1953 revealed that the site was, in fact, an Imperial palace.\"); The web check finds the claim disputed (reputable sources disagree): 17 Roman emperors were born in the land that is now Serbia (https://rogueclassicism.com/2010/04/05/itinerarium-romanum-serbiae/: \"18 Roman rulers, one fifth of all emperors, were born on its territory\") - hedge it or drop it"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 48;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s040-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s040-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s040-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 48 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
